1	import type {
2	  ArgumentMetadata,
3	  ContextType,
4	  RouteParamMetadata,
5	} from '@nestjs/common';
6	import {
7	  type CanActivate,
8	  ForbiddenException,
9	  type HttpServer,
10	  type ParamData,
11	  type PipeTransform,
12	  type RequestMethod,
13	  SSE_ABORT_CONTROLLER,
14	} from '@nestjs/common';
15	import {
16	  type Controller,
17	  CUSTOM_ROUTE_ARGS_METADATA,
18	  HEADERS_METADATA,
19	  HTTP_CODE_METADATA,
20	  isEmptyArray,
21	  isString,
22	  REDIRECT_METADATA,
23	  RENDER_METADATA,
24	  ROUTE_ARGS_METADATA,
25	  RouteParamtypes,
26	  SSE_METADATA,
27	} from '@nestjs/common/internal';
28	import type { StandardSchemaV1 } from '@standard-schema/spec';
29	import { IncomingMessage } from 'http';
30	import { Observable } from 'rxjs';
31	import {
32	  FORBIDDEN_MESSAGE,
33	  GuardsConsumer,
34	  GuardsContextCreator,
35	} from '../guards/index.js';
36	import { ContextUtils } from '../helpers/context-utils.js';
37	import { ExecutionContextHost } from '../helpers/execution-context-host.js';
38	import {
39	  HandleResponseFn,
40	  HandlerMetadata,
41	  HandlerMetadataStorage,
42	  HandlerResponseBasicFn,
43	} from '../helpers/handler-metadata-storage.js';
44	import { STATIC_CONTEXT } from '../injector/constants.js';
45	import { InterceptorsConsumer } from '../interceptors/interceptors-consumer.js';
46	import { InterceptorsContextCreator } from '../interceptors/interceptors-context-creator.js';
47	import { PipesConsumer } from '../pipes/pipes-consumer.js';
48	import { PipesContextCreator } from '../pipes/pipes-context-creator.js';
49	import { IRouteParamsFactory } from './interfaces/route-params-factory.interface.js';
50	import {
51	  CustomHeader,
52	  RedirectResponse,
53	  RouterResponseController,
54	} from './router-response-controller.js';
55	import { HeaderStream } from './sse-stream.js';
56	
57	export interface ParamProperties {
58	  index: number;
59	  type: RouteParamtypes | string;
60	  data: ParamData;
61	  pipes: PipeTransform[];
62	  extractValue: <TRequest, TResponse>(
63	    req: TRequest,
64	    res: TResponse,
65	    next: Function,
66	  ) => any;
67	  schema?: StandardSchemaV1;
68	}
69	
70	export class RouterExecutionContext {
71	  private readonly handlerMetadataStorage = new HandlerMetadataStorage();
72	  private readonly contextUtils = new ContextUtils();
73	  private readonly responseController: RouterResponseController;
74	
75	  constructor(
76	    private readonly paramsFactory: IRouteParamsFactory,
77	    private readonly pipesContextCreator: PipesContextCreator,
78	    private readonly pipesConsumer: PipesConsumer,
79	    private readonly guardsContextCreator: GuardsContextCreator,
80	    private readonly guardsConsumer: GuardsConsumer,
81	    private readonly interceptorsContextCreator: InterceptorsContextCreator,
82	    private readonly interceptorsConsumer: InterceptorsConsumer,
83	    readonly applicationRef: HttpServer,
84	  ) {
85	    this.responseController = new RouterResponseController(applicationRef);
86	  }
87	
88	  public create(
89	    instance: Controller,
90	    callback: (...args: any[]) => unknown,
91	    methodName: string,
92	    moduleKey: string,
93	    requestMethod: RequestMethod,
94	    contextId = STATIC_CONTEXT,
95	    inquirerId?: string,
96	  ) {
97	    const contextType: ContextType = 'http';
98	    const {
99	      argsLength,
100	      fnHandleResponse,
101	      isSseHandler,
102	      paramtypes,
103	      getParamsMetadata,
104	      httpStatusCode,
105	      responseHeaders,
106	      hasCustomHeaders,
107	    } = this.getMetadata(
108	      instance,
109	      callback,
110	      methodName,
111	      moduleKey,
112	      requestMethod,
113	      contextType,
114	    );
115	
116	    const paramsOptions = this.contextUtils.mergeParamsMetatypes(
117	      getParamsMetadata(moduleKey, contextId, inquirerId),
118	      paramtypes,
119	    );
120	    const pipes = this.pipesContextCreator.create(
121	      instance,
122	      callback,
123	      moduleKey,
124	      contextId,
125	      inquirerId,
126	    );
127	    const guards = this.guardsContextCreator.create(
128	      instance,
129	      callback,
130	      moduleKey,
131	      contextId,
132	      inquirerId,
133	    );
134	    const interceptors = this.interceptorsContextCreator.create(
135	      instance,
136	      callback,
137	      moduleKey,
138	      contextId,
139	      inquirerId,
140	    );
141	
142	    const fnCanActivate = this.createGuardsFn(
143	      guards,
144	      instance,
145	      callback,
146	      contextType,
147	    );
148	    const fnApplyPipes = this.createPipesFn(pipes, paramsOptions);
149	
150	    const handler =
151	      <TRequest, TResponse>(
152	        args: any[],
153	        req: TRequest,
154	        res: TResponse,
155	        next: Function,
156	      ) =>
157	      async () => {
158	        fnApplyPipes && (await fnApplyPipes(args, req, res, next));
159	        return callback.apply(instance, args);
160	      };
161	
162	    return async <TRequest, TResponse>(
163	      req: TRequest,
164	      res: TResponse,
165	      next: Function,
166	    ) => {
167	      const args = this.contextUtils.createNullArray(argsLength);
168	      fnCanActivate && (await fnCanActivate([req, res, next]));
169	
170	      this.responseController.setStatus(res, httpStatusCode);
171	      hasCustomHeaders &&
172	        this.responseController.setHeaders(res, responseHeaders);
173	
174	      if (isSseHandler) {
175	        // Attach a per-request AbortController before the handler runs so async
176	        // @Sse() handlers can observe client disconnects via @SseSignal() during
177	        // their setup. The controller is aborted in RouterResponseController.sse()
178	        // when the underlying connection closes.
179	        this.attachSseAbortSignal(req);
180	      }
181	
182	      const resultOrDeferred = this.interceptorsConsumer.intercept(
183	        interceptors,
184	        [req, res, next],
185	        instance,
186	        callback,
187	        handler(args, req, res, next),
188	        contextType,
189	      );
190	      const result = isSseHandler ? resultOrDeferred : await resultOrDeferred;
191	      await (fnHandleResponse as HandlerResponseBasicFn)(result, res, req);
192	    };
193	  }
194	
195	  public getMetadata<TContext extends ContextType = ContextType>(
196	    instance: Controller,
197	    callback: (...args: any[]) => any,
198	    methodName: string,
199	    moduleKey: string,
200	    requestMethod: RequestMethod,
201	    contextType: TContext,
202	  ): HandlerMetadata {
203	    const cacheMetadata = this.handlerMetadataStorage.get(instance, methodName);
204	    if (cacheMetadata) {
205	      return cacheMetadata;
206	    }
207	    const metadata =
208	      this.contextUtils.reflectCallbackMetadata(
209	        instance,
210	        methodName,
211	        ROUTE_ARGS_METADATA,
212	      ) || {};
213	    const keys = Object.keys(metadata);
214	    const argsLength = this.contextUtils.getArgumentsLength(keys, metadata);
215	    const paramtypes = this.contextUtils.reflectCallbackParamtypes(
216	      instance,
217	      methodName,
218	    );
219	
220	    const contextFactory = this.contextUtils.getContextFactory(
221	      contextType,
222	      instance,
223	      callback,
224	    );
225	    const getParamsMetadata = (
226	      moduleKey: string,
227	      contextId = STATIC_CONTEXT,
228	      inquirerId?: string,
229	    ) =>
230	      this.exchangeKeysForValues(
231	        keys,
232	        metadata,
233	        moduleKey,
234	        contextId,
235	        inquirerId,
236	        contextFactory,
237	      );
238	
239	    const paramsMetadata = getParamsMetadata(moduleKey);
240	    const isResponseHandled = this.isResponseHandled(
241	      instance,
242	      methodName,
243	      paramsMetadata,
244	    );
245	
246	    const httpRedirectResponse = this.reflectRedirect(callback);
247	    const fnHandleResponse = this.createHandleResponseFn(
248	      callback,
249	      isResponseHandled,
250	      httpRedirectResponse,
251	    );
252	    const isSseHandler = !!this.reflectSse(callback);
253	
254	    const httpCode = this.reflectHttpStatusCode(callback);
255	    const httpStatusCode =
256	      httpCode ?? this.responseController.getStatusByMethod(requestMethod);
257	
258	    const responseHeaders = this.reflectResponseHeaders(callback);
259	    const hasCustomHeaders = !isEmptyArray(responseHeaders);
260	    const handlerMetadata: HandlerMetadata = {
261	      argsLength,
262	      fnHandleResponse,
263	      isSseHandler,
264	      paramtypes,
265	      getParamsMetadata,
266	      httpStatusCode,
267	      hasCustomHeaders,
268	      responseHeaders,
269	    };
270	    this.handlerMetadataStorage.set(instance, methodName, handlerMetadata);
271	    return handlerMetadata;
272	  }
273	
274	  public reflectRedirect(
275	    callback: (...args: unknown[]) => unknown,
276	  ): RedirectResponse {
277	    return Reflect.getMetadata(REDIRECT_METADATA, callback);
278	  }
279	
280	  public reflectHttpStatusCode(
281	    callback: (...args: unknown[]) => unknown,
282	  ): number {
283	    return Reflect.getMetadata(HTTP_CODE_METADATA, callback);
284	  }
285	
286	  public reflectRenderTemplate(
287	    callback: (...args: unknown[]) => unknown,
288	  ): string {
289	    return Reflect.getMetadata(RENDER_METADATA, callback);
290	  }
291	
292	  public reflectResponseHeaders(
293	    callback: (...args: unknown[]) => unknown,
294	  ): CustomHeader[] {
295	    return Reflect.getMetadata(HEADERS_METADATA, callback) || [];
296	  }
297	
298	  public reflectSse(callback: (...args: unknown[]) => unknown): string {
299	    return Reflect.getMetadata(SSE_METADATA, callback);
300	  }
301	
302	  public exchangeKeysForValues(
303	    keys: string[],
304	    metadata: Record<number, RouteParamMetadata>,
305	    moduleContext: string,
306	    contextId = STATIC_CONTEXT,
307	    inquirerId?: string,
308	    contextFactory?: (args: unknown[]) => ExecutionContextHost,
309	  ): ParamProperties[] {
310	    this.pipesContextCreator.setModuleContext(moduleContext);
311	
312	    return keys.map(key => {
313	      const { index, data, pipes: pipesCollection, schema } = metadata[key];
314	      const pipes = this.pipesContextCreator.createConcreteContext(
315	        pipesCollection,
316	        contextId,
317	        inquirerId,
318	      );
319	      const type = this.contextUtils.mapParamType(key);
320	
321	      if (key.includes(CUSTOM_ROUTE_ARGS_METADATA)) {
322	        const { factory } = metadata[key];
323	        const customExtractValue = this.contextUtils.getCustomFactory(
324	          factory,
325	          data,
326	          contextFactory!,
327	        );
328	        return {
329	          index,
330	          extractValue: customExtractValue,
331	          type,
332	          data,
333	          pipes,
334	          schema,
335	        };
336	      }
337	      const numericType = Number(type);
338	      const extractValue = <TRequest, TResponse>(
339	        req: TRequest,
340	        res: TResponse,
341	        next: Function,
342	      ) =>
343	        this.paramsFactory.exchangeKeyForValue(numericType, data, {
344	          req: req as Record<string, any>,
345	          res,
346	          next,
347	        });
348	      return { index, extractValue, type: numericType, data, pipes, schema };
349	    });
350	  }
351	
352	  public async getParamValue<T>(
353	    value: T,
354	    metadata: ArgumentMetadata,
355	    pipes: PipeTransform[],
356	  ): Promise<unknown> {
357	    if (!isEmptyArray(pipes)) {
358	      return this.pipesConsumer.apply(value, metadata, pipes);
359	    }
360	    return value;
361	  }
362	
363	  public isPipeable(type: number | string): boolean {
364	    return (
365	      type === RouteParamtypes.BODY ||
366	      type === RouteParamtypes.RAW_BODY ||
367	      type === RouteParamtypes.QUERY ||
368	      type === RouteParamtypes.PARAM ||
369	      type === RouteParamtypes.FILE ||
370	      type === RouteParamtypes.FILES ||
371	      isString(type)
372	    );
373	  }
374	
375	  public createGuardsFn<TContext extends string = ContextType>(
376	    guards: CanActivate[],
377	    instance: Controller,
378	    callback: (...args: any[]) => any,
379	    contextType?: TContext,
380	  ): ((args: any[]) => Promise<void>) | null {
381	    const canActivateFn = async (args: any[]) => {
382	      const canActivate = await this.guardsConsumer.tryActivate<TContext>(
383	        guards,
384	        args,
385	        instance,
386	        callback,
387	        contextType,
388	      );
389	      if (!canActivate) {
390	        throw new ForbiddenException(FORBIDDEN_MESSAGE);
391	      }
392	    };
393	    return guards.length ? canActivateFn : null;
394	  }
395	
396	  public createPipesFn(
397	    pipes: PipeTransform[],
398	    paramsOptions: (ParamProperties & { metatype?: any })[],
399	  ) {
400	    const pipesFn = async <TRequest, TResponse>(
401	      args: any[],
402	      req: TRequest,
403	      res: TResponse,
404	      next: Function,
405	    ) => {
406	      const resolveParamValue = async (
407	        param: ParamProperties & { metatype?: any },
408	      ) => {
409	        const {
410	          index,
411	          extractValue,
412	          type,
413	          data,
414	          metatype,
415	          pipes: paramPipes,
416	          schema,
417	        } = param;
418	        const value = extractValue(req, res, next);
419	
420	        args[index] = this.isPipeable(type)
421	          ? await this.getParamValue(
422	              value,
423	              { metatype, type, data, schema } as ArgumentMetadata,
424	              pipes.concat(paramPipes),
425	            )
426	          : value;
427	      };
428	      await Promise.all(paramsOptions.map(resolveParamValue));
429	    };
430	    return paramsOptions.length ? pipesFn : null;
431	  }
432	
433	  public createHandleResponseFn(
434	    callback: (...args: unknown[]) => unknown,
435	    isResponseHandled: boolean,
436	    redirectResponse?: RedirectResponse,
437	    httpStatusCode?: number,
438	  ): HandleResponseFn {
439	    const renderTemplate = this.reflectRenderTemplate(callback);
440	    if (renderTemplate) {
441	      return async <TResult, TResponse>(result: TResult, res: TResponse) => {
442	        return await this.responseController.render(
443	          result,
444	          res,
445	          renderTemplate,
446	        );
447	      };
448	    }
449	    if (redirectResponse && isString(redirectResponse.url)) {
450	      return async <TResult, TResponse>(result: TResult, res: TResponse) => {
451	        await this.responseController.redirect(result, res, redirectResponse);
452	      };
453	    }
454	    const isSseHandler = !!this.reflectSse(callback);
455	    if (isSseHandler) {
456	      return async <
457	        TResult extends Observable<unknown> = any,
458	        TResponse extends HeaderStream = any,
459	        TRequest extends IncomingMessage = any,
460	      >(
461	        result: TResult,
462	        res: TResponse,
463	        req: TRequest,
464	      ) => {
465	        const rawResponse = (res as { raw?: TResponse }).raw ?? res;
466	        await this.responseController.sse(
467	          result,
468	          rawResponse,
469	          (req as any).raw || req,
470	          {
471	            additionalHeaders: res.getHeaders?.(),
472	            statusCode:
473	              (res as { statusCode?: number }).statusCode ??
474	              (rawResponse as { statusCode?: number }).statusCode,
475	          },
476	        );
477	      };
478	    }
479	    return async <TResult, TResponse>(result: TResult, res: TResponse) => {
480	      result = await this.responseController.transformToResult(result);
481	      !isResponseHandled &&
482	        (await this.responseController.apply(result, res, httpStatusCode));
483	      return res;
484	    };
485	  }
486	
487	  private isResponseHandled(
488	    instance: Controller,
489	    methodName: string,
490	    paramsMetadata: ParamProperties[],
491	  ): boolean {
492	    const hasResponseOrNextDecorator = paramsMetadata.some(
493	      ({ type }) =>
494	        type === RouteParamtypes.RESPONSE || type === RouteParamtypes.NEXT,
495	    );
496	    const isPassthroughEnabled = this.contextUtils.reflectPassthrough(
497	      instance,
498	      methodName,
499	    );
500	    return hasResponseOrNextDecorator && !isPassthroughEnabled;
501	  }
502	
503	  private attachSseAbortSignal<TRequest>(req: TRequest): void {
504	    const carrier = req as TRequest & {
505	      raw?: unknown;
506	      [SSE_ABORT_CONTROLLER]?: AbortController;
507	    };
508	    // Attach to both the framework request and its raw form (when present), since
509	    // @SseSignal() reads from the execution-context request while
510	    // RouterResponseController.sse() operates on the raw request.
511	    if (!carrier[SSE_ABORT_CONTROLLER]) {
512	      carrier[SSE_ABORT_CONTROLLER] = new AbortController();
513	    }
514	    if (carrier.raw && !(carrier.raw as object)[SSE_ABORT_CONTROLLER]) {
515	      (carrier.raw as object)[SSE_ABORT_CONTROLLER] =
516	        carrier[SSE_ABORT_CONTROLLER];
517	    }
518	  }
519	}
