62	export class RouterExplorer {
63	  private readonly executionContextCreator: RouterExecutionContext;
64	  private readonly pathsExplorer: PathsExplorer;
65	  private readonly routerMethodFactory = new RouterMethodFactory();
66	  private readonly logger = new Logger(RouterExplorer.name, {
67	    timestamp: true,
68	  });
69	  private readonly exceptionFiltersCache = new WeakMap();
70	
71	  constructor(
72	    metadataScanner: MetadataScanner,
73	    private readonly container: NestContainer,
74	    private readonly injector: Injector,
75	    private readonly routerProxy: RouterProxy,
76	    private readonly exceptionsFilter: ExceptionsFilter,
77	    config: ApplicationConfig,
78	    private readonly routePathFactory: RoutePathFactory,
79	    private readonly graphInspector: GraphInspector,
80	  ) {
81	    this.pathsExplorer = new PathsExplorer(metadataScanner);
82	
83	    const routeParamsFactory = new RouteParamsFactory();
84	    const pipesContextCreator = new PipesContextCreator(container, config);
85	    const pipesConsumer = new PipesConsumer();
86	    const guardsContextCreator = new GuardsContextCreator(container, config);
87	    const guardsConsumer = new GuardsConsumer();
88	    const interceptorsContextCreator = new InterceptorsContextCreator(
89	      container,
90	      config,
91	    );
92	    const interceptorsConsumer = new InterceptorsConsumer();
93	
94	    this.executionContextCreator = new RouterExecutionContext(
95	      routeParamsFactory,
96	      pipesContextCreator,
97	      pipesConsumer,
98	      guardsContextCreator,
99	      guardsConsumer,
100	      interceptorsContextCreator,
101	      interceptorsConsumer,
102	      container.getHttpAdapterRef(),
