106	  public explore<T extends HttpServer = any>(
107	    instanceWrapper: InstanceWrapper,
108	    moduleKey: string,
109	    httpAdapterRef: T,
110	    host: string | RegExp | Array<string | RegExp>,
111	    routePathMetadata: RoutePathMetadata,
112	    options: RouteResolutionOptions = {},
113	  ) {
114	    const { instance } = instanceWrapper;
115	    const routerPaths = this.pathsExplorer.scanForPaths(instance);
116	    this.applyPathsToRouterProxy(
117	      httpAdapterRef,
118	      routerPaths,
119	      instanceWrapper,
120	      moduleKey,
121	      routePathMetadata,
122	      host,
123	      options,
124	    );
125	  }
