127	  public extractRouterPath(metatype: Type<Controller>): string[] {
128	    const path = Reflect.getMetadata(PATH_METADATA, metatype);
129	
130	    if (isUndefined(path)) {
131	      throw new UnknownRequestMappingException(metatype);
132	    }
133	    if (Array.isArray(path)) {
134	      return path.map(p => addLeadingSlash(p));
135	    }
136	    return [addLeadingSlash(path)];
