139	  public applyPathsToRouterProxy<T extends HttpServer>(
140	    router: T,
141	    routeDefinitions: RouteDefinition[],
142	    instanceWrapper: InstanceWrapper,
143	    moduleKey: string,
144	    routePathMetadata: RoutePathMetadata,
145	    host: string | RegExp | Array<string | RegExp>,
146	    options: RouteResolutionOptions = {},
147	  ) {
148	    (routeDefinitions || []).forEach(routeDefinition => {
149	      const { version: methodVersion } = routeDefinition;
150	      routePathMetadata.methodVersion = methodVersion;
151	
152	      this.applyCallbackToRouter(
153	        router,
154	        routeDefinition,
155	        instanceWrapper,
156	        moduleKey,
157	        routePathMetadata,
158	        host,
159	        options,
160	      );
161	    });
162	  }
163	
164	  private applyCallbackToRouter<T extends HttpServer>(
165	    router: T,
166	    routeDefinition: RouteDefinition,
167	    instanceWrapper: InstanceWrapper,
168	    moduleKey: string,
169	    routePathMetadata: RoutePathMetadata,
170	    host: string | RegExp | Array<string | RegExp>,
171	    options: RouteResolutionOptions = {},
172	  ) {
173	    const { onRouteResolved, deferRegistration = false } = options;
174	    const {
175	      path: paths,
176	      requestMethod,
177	      targetCallback,
178	      methodName,
179	    } = routeDefinition;
180	
181	    const { instance } = instanceWrapper;
182	    const routerMethodRef = this.routerMethodFactory
183	      .get(router, requestMethod)
184	      .bind(router);
185	
186	    const isRequestScoped = !instanceWrapper.isDependencyTreeStatic();
187	    const proxy = isRequestScoped
188	      ? this.createRequestScopedHandler(
189	          instanceWrapper,
190	          requestMethod,
191	          this.container.getModuleByKey(moduleKey)!,
192	          moduleKey,
193	          methodName,
194	        )
195	      : this.createCallbackProxy(
196	          instance,
197	          targetCallback,
198	          methodName,
199	          moduleKey,
200	          requestMethod,
201	        );
202	
203	    const isVersioned =
204	      (routePathMetadata.methodVersion ||
205	        routePathMetadata.controllerVersion) &&
206	      routePathMetadata.versioningOptions;
207	    let routeHandler = this.applyHostFilter(host, proxy);
208	
209	    paths.forEach(path => {
210	      if (
211	        isVersioned &&
212	        routePathMetadata.versioningOptions!.type !== VersioningType.URI
213	      ) {
214	        // All versioning (except for URI Versioning) is done via the "Version Filter"
215	        routeHandler = this.applyVersionFilter(
216	          router,
217	          routePathMetadata,
218	          routeHandler,
219	        );
220	      }
221	
222	      routePathMetadata.methodPath = path;
223	      const pathsToRegister = this.routePathFactory.create(
224	        routePathMetadata,
225	        requestMethod,
226	      );
227	      pathsToRegister.forEach(path => {
228	        const normalizedPath = router.normalizePath
229	          ? router.normalizePath(path)
230	          : path;
231	        const entrypointDefinition: Entrypoint<HttpEntrypointMetadata> = {
232	          type: 'http-endpoint',
233	          methodName,
234	          className: instanceWrapper.name,
235	          classNodeId: instanceWrapper.id,
236	          metadata: {
237	            key: path,
238	            path,
239	            requestMethod: RequestMethod[
240	              requestMethod
241	            ] as keyof typeof RequestMethod,
242	            methodVersion: routePathMetadata.methodVersion,
243	            controllerVersion: routePathMetadata.controllerVersion,
244	          },
245	        };
246	
247	        if (!deferRegistration) {
248	          this.copyMetadataToCallback(targetCallback, routeHandler);
249	
250	          const httpAdapter = this.container.getHttpAdapterRef();
251	          const onRouteTriggered = httpAdapter.getOnRouteTriggered?.();
252	          if (onRouteTriggered) {
253	            routerMethodRef(normalizedPath, (...args: unknown[]) => {
254	              onRouteTriggered(requestMethod, path);
255	              return routeHandler(...args);
256	            });
257	          } else {
258	            routerMethodRef(normalizedPath, routeHandler);
259	          }
260	        }
261	
262	        onRouteResolved?.({
263	          method: requestMethod,
264	          path: normalizedPath,
265	          rawPath: path,
266	          host,
267	          version:
268	            routePathMetadata.methodVersion ??
269	            routePathMetadata.controllerVersion,
270	          methodVersion: routePathMetadata.methodVersion,
271	          controllerVersion: routePathMetadata.controllerVersion,
272	          handler: routeHandler as unknown as (...args: unknown[]) => unknown,
273	          targetCallback,
274	          methodName,
275	          instanceWrapper,
276	        });
277	
278	        this.graphInspector.insertEntrypointDefinition<HttpEntrypointMetadata>(
279	          entrypointDefinition,
280	          instanceWrapper.id,
281	        );
282	      });
283	
284	      const pathsToLog = this.routePathFactory.create(
285	        {
286	          ...routePathMetadata,
287	          versioningOptions: undefined,
288	        },
289	        requestMethod,
290	      );
291	      pathsToLog.forEach(path => {
292	        if (isVersioned) {
293	          const version = this.routePathFactory.getVersion(routePathMetadata);
294	          this.logger.log(
295	            VERSIONED_ROUTE_MAPPED_MESSAGE(path, requestMethod, version!),
296	          );
297	        } else {
298	          this.logger.log(ROUTE_MAPPED_MESSAGE(path, requestMethod));
299	        }
300	      });
301	    });
302	  }
303	
304	  /**
305	   * Registers a previously resolved route on the underlying HTTP adapter.
306	   * Used when route registration has been deferred (e.g. when sorting
307	   * routes by specificity) so the caller can choose the order in which
308	   * routes are installed on the adapter.
309	   */
310	  public registerResolvedRoute<T extends HttpServer>(
311	    router: T,
312	    route: ResolvedRoute,
313	  ): void {
314	    const routerMethodRef = this.routerMethodFactory
315	      .get(router, route.method)
316	      .bind(router);
317	
318	    this.copyMetadataToCallback(route.targetCallback, route.handler);
319	    const normalizedPath = route.path;
320	    const rawPath = route.rawPath ?? route.path;
321	
322	    const httpAdapter = this.container.getHttpAdapterRef();
323	    const onRouteTriggered = httpAdapter.getOnRouteTriggered?.();
324	    if (onRouteTriggered) {
325	      routerMethodRef(normalizedPath, (...args: unknown[]) => {
326	        onRouteTriggered(route.method, rawPath);
327	        return route.handler(...args);
328	      });
329	    } else {
330	      routerMethodRef(normalizedPath, route.handler);
331	    }
332	  }
333	
334	  private applyHostFilter(
335	    host: string | RegExp | Array<string | RegExp>,
336	    handler: Function,
337	  ) {
338	    if (!host) {
339	      return handler;
340	    }
341	
342	    const httpAdapterRef = this.container.getHttpAdapterRef();
343	    const hosts = Array.isArray(host) ? host : [host];
344	    const hostRegExps = hosts.map((host: string | RegExp) => {
345	      if (typeof host === 'string') {
346	        try {
347	          return pathToRegexp(host);
348	        } catch (e) {
349	          if (e instanceof TypeError) {
350	            this.logger.error(
351	              `Unsupported host "${host}" syntax. In past releases, ?, *, and + were used to denote optional or repeating path parameters. The latest version of "path-to-regexp" now requires the use of named parameters. For example, instead of using a route like /users/* to capture all routes starting with "/users", you should use /users/*path. Please see the migration guide for more information.`,
352	            );
353	          }
354	          throw e;
355	        }
356	      }
357	      return { regexp: host, keys: [] };
358	    });
359	
360	    const unsupportedFilteringErrorMessage = Array.isArray(host)
361	      ? `HTTP adapter does not support filtering on hosts: ["${host.join(
362	          '", "',
363	        )}"]`
364	      : `HTTP adapter does not support filtering on host: "${host}"`;
365	
366	    return <TRequest extends Record<string, any> = any, TResponse = any>(
367	      req: TRequest,
368	      res: TResponse,
369	      next: () => void,
370	    ) => {
371	      (req as Record<string, any>).hosts = {};
372	      const hostname = httpAdapterRef.getRequestHostname(req) || '';
373	
374	      for (const exp of hostRegExps) {
375	        const match = hostname.match(exp.regexp);
376	        if (match) {
377	          if (exp.keys.length > 0) {
378	            exp.keys.forEach((key, i) => (req.hosts[key.name] = match[i + 1]));
379	          } else if (exp.regexp && match.groups) {
380	            for (const groupName in match.groups) {
381	              req.hosts[groupName] = match.groups[groupName];
382	            }
383	          }
384	          return handler(req, res, next);
385	        }
386	      }
387	      if (!next) {
388	        throw new InternalServerErrorException(
389	          unsupportedFilteringErrorMessage,
390	        );
391	      }
392	      return next();
393	    };
394	  }
395	
396	  private applyVersionFilter<T extends HttpServer>(
397	    router: T,
398	    routePathMetadata: RoutePathMetadata,
399	    handler: Function,
400	  ) {
401	    const version = this.routePathFactory.getVersion(routePathMetadata)!;
402	    return router.applyVersionFilter(
403	      handler,
404	      version,
405	      routePathMetadata.versioningOptions!,
406	    );
407	  }
408	
409	  private createCallbackProxy(
410	    instance: Controller,
411	    callback: RouterProxyCallback,
412	    methodName: string,
413	    moduleRef: string,
414	    requestMethod: RequestMethod,
415	    contextId = STATIC_CONTEXT,
416	    inquirerId?: string,
417	  ) {
418	    const executionContext = this.executionContextCreator.create(
419	      instance,
420	      callback,
421	      methodName,
422	      moduleRef,
423	      requestMethod,
424	      contextId,
425	      inquirerId,
426	    );
427	    const exceptionFilter = this.exceptionsFilter.create(
428	      instance,
429	      callback,
430	      moduleRef,
431	      contextId,
432	      inquirerId,
433	    );
434	    return this.routerProxy.createProxy(executionContext, exceptionFilter);
435	  }
436	
437	  public createRequestScopedHandler(
438	    instanceWrapper: InstanceWrapper,
439	    requestMethod: RequestMethod,
440	    moduleRef: Module,
441	    moduleKey: string,
442	    methodName: string,
443	  ) {
444	    const { instance } = instanceWrapper;
445	    const collection = moduleRef.controllers;
446	
447	    const isTreeDurable = instanceWrapper.isDependencyTreeDurable();
448	
449	    return async <TRequest extends Record<any, any>, TResponse>(
450	      req: TRequest,
451	      res: TResponse,
452	      next: () => void,
453	    ) => {
454	      try {
455	        const contextId = this.getContextId(req, isTreeDurable);
456	        const contextInstance = await this.injector.loadPerContext(
457	          instance,
458	          moduleRef,
459	          collection,
460	          contextId,
461	        );
462	        await this.createCallbackProxy(
463	          contextInstance,
464	          contextInstance[methodName],
465	          methodName,
466	          moduleKey,
467	          requestMethod,
468	          contextId,
469	          instanceWrapper.id,
470	        )(req, res, next);
471	      } catch (err) {
472	        let exceptionFilter = this.exceptionFiltersCache.get(
473	          instance[methodName],
474	        );
475	        if (!exceptionFilter) {
476	          exceptionFilter = this.exceptionsFilter.create(
477	            instance,
478	            instance[methodName],
479	            moduleKey,
480	          );
481	          this.exceptionFiltersCache.set(instance[methodName], exceptionFilter);
482	        }
483	        const host = new ExecutionContextHost([req, res, next]);
484	        exceptionFilter.next(err, host);
485	      }
486	    };
487	  }
488	
489	  private getContextId<T extends Record<any, unknown> = any>(
490	    request: T,
491	    isTreeDurable: boolean,
492	  ): ContextId {
493	    const contextId = ContextIdFactory.getByRequest(request);
494	    if (!request[REQUEST_CONTEXT_ID as any]) {
495	      Object.defineProperty(request, REQUEST_CONTEXT_ID, {
496	        value: contextId,
497	        enumerable: false,
498	        writable: false,
499	        configurable: false,
500	      });
501	
502	      const requestProviderValue = isTreeDurable
503	        ? contextId.payload
504	        : Object.assign(request, contextId.payload);
505	      this.container.registerRequestProvider(requestProviderValue, contextId);
506	    }
507	    return contextId;
508	  }
509	
510	  private copyMetadataToCallback(
511	    originalCallback: RouterProxyCallback,
512	    targetCallback: Function,
513	  ) {
514	    for (const key of Reflect.getMetadataKeys(originalCallback)) {
515	      Reflect.defineMetadata(
516	        key,
517	        Reflect.getMetadata(key, originalCallback),
518	        targetCallback,
519	      );
520	    }
521	  }
522	}
